    int x, t, a, b, da, db;

    while (scanf("%d%d%d%d%d%d", &x, &t, &a, &b, &da, &db) == 6) {
        vector<long long> coa(t), cob(t);

        for (int i = 0; i < t; ++i) {
            coa[i] = max(0LL, static_cast<long long>(a) - 1LL * i * da);
            cob[i] = max(0LL, static_cast<long long>(b) - 1LL * i * db);
        }

        bool found = false;
        for (int i = 0; i < t && !found; ++i) {
            for (int j = i + 1; j < t; ++j) {
                if ((coa[i] > 0 && cob[j] > 0 && coa[i] + cob[j] == x) ||
                    (cob[i] > 0 && coa[j] > 0 && cob[i] + coa[j] == x)) {
                    found = true;
                    break;
                }
            }
        }

        puts(found ? "YES" : "NO");
    }

    return 0;
}

