    cin.tie(nullptr);

    long long x, t, a, b, da, db;

    while (cin >> x >> t >> a >> b >> da >> db) {
        vector<long long> coa(t, 0), cob(t, 0);

        for (long long i = 0; i < t; ++i) {
            coa[i] = max(0LL, a - i * da);
            cob[i] = max(0LL, b - i * db);
        }

        bool found = false;
        for (long long i = 0; i < t && !found; ++i) {
            if (coa[i] == 0) continue;

