using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long x, t, a, b, da, db;

    while (cin >> x >> t >> a >> b >> da >> db) {
        unordered_set<long long> previousA, previousB;
        bool found = false;

        for (long long i = 0; i < t && !found; ++i) {
            long long currentA = a - i * da;
            long long currentB = b - i * db;

            if (currentB > 0 && previousA.count(x - currentB))
                found = true;
            if (currentA > 0 && previousB.count(x - currentA))
                found = true;

            if (currentA > 0)
                previousA.insert(currentA);
            if (currentB > 0)
                previousB.insert(currentB);
        }

        cout << (found ? "YES\n" : "NO\n");
    }

    return 0;
}

